   private static int uniform(String name) {
      return GL20C.glGetUniformLocation(program, name);
   }

   record Layout(int inStrideU, int inPosU, int inUv0U, int inUv2U, int inColorU, int outStrideB, int outPosB, int outNormalB) {
   }
